function validate(input) {
  const [{ Student = [], Department = [] }] = input;
  const depts = new Set(), students = new Set();
  for (const [id] of Department) {
    if (id === null) return 'Every department needs a dept_id.';
    if (depts.has(id)) return `dept_id ${id} appears twice in Department.`;
    depts.add(id);
  }
  for (const [id, , gender, dept] of Student) {
    if (id === null) return 'Every student needs a student_id.';
    if (students.has(id)) return `student_id ${id} appears twice in Student.`;
    if (gender !== 'M' && gender !== 'F') return `gender must be M or F, not ${gender}.`;
    if (!depts.has(dept)) return `Student ${id} has unknown dept_id ${dept}.`;
    students.add(id);
  }
  return null;
}

generator:
function generate(rand, size) {
  const pool = ['Engineering', 'Science', 'Law', 'Art', 'Music', 'History', 'Biology', 'Physics'];
  const first = ['Jack', 'Jane', 'Mark', 'Ana', 'Lee', 'Kim', 'Ravi', 'Sofia'];
  const Department = [], Student = [];
  const deptCount = size === 'small' ? Math.floor(rand() * 7) : 300;
  // Shuffle ids so that dept_id order differs from name order.
  const ids = Array.from({ length: deptCount }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  ids.forEach((id, i) => Department.push([id, i < pool.length ? pool[i] : `${pool[i % pool.length]} ${Math.floor(i / pool.length)}`]));
  const studentCount = deptCount === 0 ? 0 : size === 'small' ? Math.floor(rand() * 9) : 2000;
  const busy = Math.max(1, Math.ceil(deptCount * 0.7));
  for (let id = 1; id <= studentCount; id++) {
    const dept = ids[Math.floor(rand() * busy)];
    Student.push([id, first[Math.floor(rand() * first.length)], rand() < 0.5 ? 'M' : 'F', dept]);
  }
  return [{ Student, Department }];
}
